#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.40.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.40.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
JS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.40.0.js').read_text()
IK=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-integrated-knowledge-v1.js').read_text()
NB=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-notebook-v8.js').read_text()
PORT=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-portability-v1.js').read_text()
REVIEW=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-review-provenance-v1.js').read_text()
def c(x,l):
 if not x: raise SystemExit('FAIL - '+l)
 print('PASS - '+l)
c('Version: 0.40.0' in MAIN,'plugin version')
c((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.40.0','0.39.0','Integrated Knowledge Workspace'),'manifest release lineage')
c((MAN['storage_schema_version'],MAN['project_schema'],MAN['export_schema'])==(35,'sc-workspace-project/20.0','sc-workspace-project-export/20.0'),'schema-stable storage 35 / project 20 / export 20')
c(not MAN['schema_migration_required'] and MAN['migration']['schema_stable'] and MAN['migration']['storage_from']==35 and MAN['migration']['storage_to']==35 and MAN['migration']['project_schema_unchanged'],'schema-stable consolidation boundary')
c(MAN['notebook_workspace_schema']=='sc-workspace-notebook-workspace/8.0' and MAN['notebook_export_schema']=='sc-workspace-notebook-export/8.0','Notebook Workspace/Export v8 retained')
c(MAN['integrated_knowledge_schema']=='sc-workspace-integrated-knowledge/1.0' and MAN['integrated_knowledge_ref_schema']=='sc-workspace-integrated-knowledge-ref/1.0','Integrated Knowledge schemas')
c('/wp-json/sc-workspace/v1/integrated-knowledge-contract' in MAN['rest_routes'] and "'/integrated-knowledge-contract'" in PHP,'Integrated Knowledge REST contract')
c(all(x in IK for x in ("kind:'object'","kind:'notebook'","kind:'notebook-block'","kind:'research-question'","kind:'research-claim'",'function derive(state)','function filter(entries,prefs={})','function connections(target,state)')),'cross-surface derived index')
c(all(x in PHP for x in ('data-scw-workspace-view="research"','INTEGRATED KNOWLEDGE WORKSPACE','data-scw-integrated-search','data-scw-integrated-results','data-scw-integrated-detail')),'Integrated Knowledge presentation')
c("workspaceView === 'research'" in JS and 'renderIntegratedKnowledge()' in JS and 'openIntegratedEntry(entry)' in JS,'Integrated Knowledge browser routing')
g=MAN['governance']
c(g['integrated_knowledge_derived'] and not g['integrated_knowledge_duplicates_canonical_content'],'derived canonical records / no duplicate content store')
c(not g['integrated_knowledge_automatic_semantic_inference'] and not g['integrated_knowledge_automatic_ai'] and not g['integrated_knowledge_automatic_mutation'],'no semantic inference / AI / mutation')
c('expectedRevision' in PORT and 'silentLastWriteWins:false' in PORT,'v0.38 conflict-safe notebook sync retained')
c(all(x in REVIEW for x in ('buildReview','buildReconciliation','shadowProvenanceDatabase:false','automaticInference:false')),'v0.39 Notebook Review & Provenance retained')
c("WORKSPACE_SCHEMA='sc-workspace-notebook-workspace/8.0'" in NB,'Notebook v8 runtime retained')
c((REG['public_version'],REG['previous_version'])==('0.40.0','0.39.0'),'registry lineage')
c("BACKUP_KEY = 'sc_workspace_registry_backup_v0400'" in REGPHP and 'LEGACY_PENDING_KEY_V0390' in REGPHP,'registry retry lineage')
c((ROOT/'history/release-manifest-v0.39.0.json').exists() and (ROOT/'history/workspace-product-record-v0.39.0.json').exists(),'v0.39 history preserved')
files=list((ROOT/'schemas').glob('*.json'))+[ROOT/'release-manifest-v0.40.0.json',ROOT/'registry/workspace-product-record-v0.40.0.json']
for p in files: json.loads(p.read_text())
print(f'PASS - {len(files)} JSON schema/release records')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.40.0 — Integrated Knowledge Workspace')
